def mark_existing_paid(apps, schema_editor):
    """Khoản hoàn ghi trước GD-07 đã gắn ca lúc duyệt: coi là đã hoàn tại ca đó, gắn thanh toán gốc."""
    Refund = apps.get_model("shifts", "Refund")
    Order = apps.get_model("orders", "Order")
    for r in Refund.objects.all():
        order = Order.objects.filter(code=r.order_code).first()
        r.payment_id = order.payment_id if order else None
        if r.shift_id:
            r.status, r.paid_at, r.paid_by_id = "da_hoan", r.created_at, r.approved_by_id
        r.save()


